--
-- Table structure for table `order_item`
--

DROP TABLE IF EXISTS `order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_item` (
  `id` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `quantity` int unsigned NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `menu_item_id` char(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_id` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `allergens` json NOT NULL DEFAULT (_utf8mb4'[]'),
  `batch_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cook_seconds_actual` int unsigned NOT NULL,
  `cook_seconds_estimate` int unsigned NOT NULL,
  `fired_at` datetime(6) DEFAULT NULL,
  `hold_until` datetime(6) DEFAULT NULL,
  `meta` json NOT NULL DEFAULT (_utf8mb4'{}'),
  `modifiers` json NOT NULL DEFAULT (_utf8mb4'[]'),
  `notes` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ready_at` datetime(6) DEFAULT NULL,
  `sequence` int unsigned NOT NULL,
  `state` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `station_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `station_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customize` longtext COLLATE utf8mb4_unicode_ci,
  `size` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_item_order_i_08a5da_idx` (`order_id`),
  KEY `order_item_menu_item_id_cb981a32_fk_menu_item_id` (`menu_item_id`),
  KEY `order_item_station_state_idx` (`station_code`,`state`),
  KEY `order_item_batch_idx` (`batch_id`),
  CONSTRAINT `order_item_menu_item_id_cb981a32_fk_menu_item_id` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_item` (`id`),
  CONSTRAINT `order_item_order_id_0ca9e92e_fk_order_id` FOREIGN KEY (`order_id`) REFERENCES `order` (`id`),
  CONSTRAINT `order_item_chk_1` CHECK ((`quantity` >= 0)),
  CONSTRAINT `order_item_chk_2` CHECK ((`cook_seconds_actual` >= 0)),
  CONSTRAINT `order_item_chk_3` CHECK ((`cook_seconds_estimate` >= 0)),
  CONSTRAINT `order_item_chk_4` CHECK ((`sequence` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

